INSERT INTO purpose VALUES('core-content','boundary::NodeIndex','struct','Names a node''s position in a content table, which a former''s child edge and a root placement point at.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','boundary::Occurrence','struct','Names how many items of the same key precede an item, so a reference names a repeated key''s one occurrence.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::Bytes','struct','Wraps a borrowed run of bytes, so a writer frames it with its length.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::CodataWrite','enum','States whether a sink takes a codata application, so a store refuses it and a key admits it.',NULL,'fits','sound',NULL);
