INSERT INTO purpose VALUES('core-content','codec::read_literal','function','Reads one literal of the kernel''s vocabulary.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::read_node','function','Reads one content node, so a table rebuilds node by node.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::read_nodes','function','Reads a supported table and rebuilds the former and the scope of each node.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::read_pasting','function','Reads the pasting that a composite names.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::read_reference','function','Reads a reference to an item, a node or a source.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','codec::read_row_tail','function','Reads the tail of a row literal: absent, or the row term that it names.',NULL,'fits','sound',NULL);
