INSERT INTO purpose VALUES('core-content','content::ArenaNode','enum','Names a node of a core arena of any of the four sorts: the root a table is read from or minted to.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','content::CellsRoots','struct','Holds the free cells a type of words is minted over, its sort named by reference, not by position.',NULL,'fits','sound',NULL);
