INSERT INTO purpose VALUES('core-content','content::Encoder','struct','Numbers an arena graph by discovery in a breadth-first walk, so equal graphs give equal tables.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','content::MintEntry','trait','Lets one mint read a de Bruijn table and a supported table alike.',NULL,'fits','sound',NULL);
