INSERT INTO purpose VALUES('core-content','content::PresentationRoots','struct','Holds the rules that present a nominal type and the cells of a type of words, as content.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','content::Sort','enum','Names the four node sorts of the core vocabulary: value, computation, value type, computation type.',NULL,'fits','sound',NULL);
