INSERT INTO purpose VALUES('core-content','content::occurring','module','Names the reason no occurrence is named.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','content::referencing','module','Names the reason no reference is named.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','content::seating','module','Names the reason no node was minted.',NULL,'fits','sound',NULL);
