INSERT INTO purpose VALUES('core-content','content::tabled_roots','function','Gives the content table of a set of arena roots, constants placed through a resolver, and the place of each root in it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-content','content::words','module','Names the reason no cell is held.',NULL,'fits','sound',NULL);
